import{_ as t,a,o,a6 as d}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"Catalog Categories — Tree (Nested)","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-catalog-categories-tree","title":"Category Tree (Nested)","description":"Full nested category tree. Returns a JSON array of root nodes, each carrying its full subtree under `children`. Supports optional locale, status, and rootId filters.","query":"curl -X GET \\"https://your-domain.com/api/admin/catalog/categories/tree?locale=en&status=1\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: application/json\\"\\n","variables":"locale=en&status=1\\n","response":"{\\n  \\"data\\": [\\n    {\\n      \\"id\\": 1,\\n      \\"name\\": \\"Root Category\\",\\n      \\"slug\\": \\"root\\",\\n      \\"status\\": 1,\\n      \\"position\\": 0,\\n      \\"parentId\\": null,\\n      \\"displayMode\\": null,\\n      \\"children\\": [\\n        {\\n          \\"id\\": 2,\\n          \\"name\\": \\"Apparel\\",\\n          \\"slug\\": \\"apparel\\",\\n          \\"status\\": 1,\\n          \\"position\\": 1,\\n          \\"parentId\\": 1,\\n          \\"displayMode\\": null,\\n          \\"children\\": []\\n        },\\n        {\\n          \\"id\\": 5,\\n          \\"name\\": \\"Electronics\\",\\n          \\"slug\\": \\"electronics\\",\\n          \\"status\\": 1,\\n          \\"position\\": 2,\\n          \\"parentId\\": 1,\\n          \\"displayMode\\": null,\\n          \\"children\\": []\\n        }\\n      ]\\n    }\\n  ],\\n  \\"meta\\": {\\n    \\"currentPage\\": 1,\\n    \\"perPage\\": 50,\\n    \\"lastPage\\": 1,\\n    \\"total\\": 1,\\n    \\"from\\": 1,\\n    \\"to\\": 1\\n  }\\n}\\n","commonErrors":[{"error":"Unauthorized (401)","cause":"Missing, invalid, expired, or revoked admin Bearer token","solution":"Send a valid admin Bearer token (Integration token) in the Authorization header. See the Authentication page."}]}]},"headers":[],"relativePath":"api/rest-api/admin/catalog/categories/categories-tree.md","filePath":"api/rest-api/admin/catalog/categories/categories-tree.md","lastUpdated":1787290888000}'),r={name:"api/rest-api/admin/catalog/categories/categories-tree.md"};function n(i,e,s,l,c,h){return o(),a("div",null,e[0]||(e[0]=[d('<h1 id="catalog-categories-—-tree-nested" tabindex="-1">Catalog Categories — Tree (Nested) <a class="header-anchor" href="#catalog-categories-—-tree-nested" aria-label="Permalink to &quot;Catalog Categories — Tree (Nested)&quot;">​</a></h1><p>Returns the full nested category hierarchy for the admin <strong>Catalog → Categories</strong> tree view. Each node carries the same scalar fields as the flat listing plus a <code>children</code> array containing its full subtree. Leaf nodes have <code>children: []</code>.</p><p>This endpoint returns the <strong>nested hierarchy</strong>, which is what a tree picker or navigation menu needs. For a flat, filterable, sortable list use <a href="/api/rest-api/admin/catalog/categories/categories-listing.html"><code>GET /api/admin/catalog/categories</code></a> instead.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th><th>Authentication</th></tr></thead><tbody><tr><td><code>/api/admin/catalog/categories/tree</code></td><td>GET</td><td>Admin Bearer token</td></tr></tbody></table><h2 id="query-parameters" tabindex="-1">Query Parameters <a class="header-anchor" href="#query-parameters" aria-label="Permalink to &quot;Query Parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>locale</code></td><td>string</td><td>Locale code for name/slug resolution (default: app locale)</td><td><code>en</code></td></tr><tr><td><code>status</code></td><td>integer</td><td>Filter by status: <code>0</code> = disabled, <code>1</code> = enabled. Ancestor nodes are preserved even when they are disabled, so children of the matching status remain reachable.</td><td><code>1</code></td></tr><tr><td><code>rootId</code></td><td>integer</td><td>Limit the tree to descendants of this category ID (inclusive). Returns an empty array if the ID is unknown.</td><td><code>1</code></td></tr></tbody></table><h2 id="response-shape" tabindex="-1">Response Shape <a class="header-anchor" href="#response-shape" aria-label="Permalink to &quot;Response Shape&quot;">​</a></h2><p>The response uses the standard admin <code>{ data, meta }</code> envelope. The <code>data</code> array contains root-level category nodes. Each node has the same scalar fields and a <code>children</code> array with its subtree.</p><h3 id="node-fields" tabindex="-1">Node fields <a class="header-anchor" href="#node-fields" aria-label="Permalink to &quot;Node fields&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Category ID</td></tr><tr><td><code>name</code></td><td>string|null</td><td>Category name resolved via <code>locale</code></td></tr><tr><td><code>slug</code></td><td>string|null</td><td>URL slug</td></tr><tr><td><code>status</code></td><td>integer</td><td><code>1</code> = enabled, <code>0</code> = disabled</td></tr><tr><td><code>position</code></td><td>integer</td><td>Display order position</td></tr><tr><td><code>parentId</code></td><td>integer|null</td><td>Parent category ID; <code>null</code> for root nodes</td></tr><tr><td><code>displayMode</code></td><td>string|null</td><td>Category display mode (e.g. <code>products_and_description</code>)</td></tr><tr><td><code>children</code></td><td>array</td><td>Nested child nodes (recursive); <code>[]</code> for leaf nodes</td></tr></tbody></table><h3 id="meta-object" tabindex="-1"><code>meta</code> object <a class="header-anchor" href="#meta-object" aria-label="Permalink to &quot;`meta` object&quot;">​</a></h3><p>The <code>meta</code> object counts <strong>root nodes</strong>, not individual categories. It uses <code>perPage: 50</code> by default and <code>total: N</code> where N is the number of top-level nodes after filtering.</p><h2 id="filtering-with-rootid" tabindex="-1">Filtering with <code>rootId</code> <a class="header-anchor" href="#filtering-with-rootid" aria-label="Permalink to &quot;Filtering with `rootId`&quot;">​</a></h2><p>Pass <code>?rootId=&lt;id&gt;</code> to return only the subtree rooted at that category ID (the node itself plus all descendants):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> GET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://your-domain.com/api/admin/catalog/categories/tree?rootId=2&amp;locale=en&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer &lt;token&gt;&quot;</span></span></code></pre></div><p>If the <code>rootId</code> does not exist in the database, the response is <code>{ &quot;data&quot;: [], &quot;meta&quot;: { ... &quot;total&quot;: 0 } }</code>.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>HTTP</th><th>Detail</th></tr></thead><tbody><tr><td><code>401</code></td><td><code>Unauthenticated.</code></td></tr></tbody></table><p>An unknown <code>?rootId</code> is not an error — it returns <code>data: []</code> with <code>total: 0</code>.</p><h2 id="behaviour-worth-knowing" tabindex="-1">Behaviour Worth Knowing <a class="header-anchor" href="#behaviour-worth-knowing" aria-label="Permalink to &quot;Behaviour Worth Knowing&quot;">​</a></h2><ul><li><strong>Everything arrives inline.</strong> <code>children</code> is a plain nested array, not an IRI reference, so one call returns the whole tree with no follow-up requests.</li><li><strong>Pagination counts root nodes, not categories.</strong> Each matched root always arrives with its complete subtree, so a store with a single root reports <code>total: 1</code> however many categories sit beneath it. Scope a large catalog with <code>?rootId=&lt;id&gt;</code> rather than by paging.</li><li><strong><code>status</code> filtering keeps ancestors.</strong> With <code>?status=1</code>, a disabled parent still appears when any descendant is enabled, so the branch stays reachable; non-matching leaves are pruned.</li><li><strong>Nodes are slim by design</strong> — <code>id</code>, <code>name</code>, <code>slug</code>, <code>status</code>, <code>position</code>, <code>parentId</code>, <code>displayMode</code>, and <code>children</code>. There is no <code>locale</code>, and no translations or filterable attribute ids; names and slugs are already resolved for the requested locale. Use <a href="/api/rest-api/admin/catalog/categories/categories-detail.html">the detail endpoint</a> when you need per-locale metadata.</li><li><strong><code>id</code> is the numeric category id at every level</strong>, unlike the GraphQL tree, whose top-level nodes expose an IRI in <code>id</code> and the number in <code>_id</code>.</li></ul>',22)]))}const g=t(r,[["render",n]]);export{u as __pageData,g as default};
